import React from "react";

const iconColors = {
  green: "bg-green-50 text-green-700",
  amber: "bg-amber-50 text-amber-700",
  blue: "bg-blue-50 text-blue-700",
  mint: "bg-emerald-50 text-emerald-700",
};

const StatCard = ({ title, value, change, note, icon, tone }) => (
  <section className="rounded-xl border border-gray-100 bg-white p-4 sm:p-5">
    <div className="flex items-center justify-between text-[10px] font-semibold text-gray-500">
      <span>{title}</span>
      <i
        className={`grid h-8 w-8 place-items-center rounded-lg text-base not-italic ${
          iconColors[tone]
        }`}
      >
        {icon}
      </i>
    </div>
    <div className="my-2 font-['Manrope',sans-serif] text-2xl font-bold tracking-tight text-[#17251d]">
      {value}
    </div>
    <div className="flex flex-wrap gap-x-2 text-[9px] text-gray-400">
      <b className="text-[#388457]">{change}</b>
      <span>{note}</span>
    </div>
  </section>
);

export default StatCard;
